const sceneTheme={meadow:0,cave:1,desert:2,sky:3,ice:4,forest:5,night:6,volcano:7,water:3,fortress:6};
function createLevel(n){
 const plan=stagePlans[n],ground=[],blocks=[],pipes=[],enemies=[],coins=[],items=[],platforms=[],springs=[],hazards=[],chunks=[];
 let x=0;for(const token of plan.route.split(' ')){const [len,top]=token.split('/'),w=Number(len),y=top==='-'?null:Number(top);const g={x,y,w,h:y===null?0:570-y};chunks.push(g);if(y!==null)ground.push(g);x+=w}
 const arenaStart=x;ground.push({x,y:450,w:n%4===3?1000:380,h:120});const width=x+(n%4===3?1000:380);
 for(const [j,segment] of (plan.blocks||[]).entries()){const g=chunks[segment],bx=g.x+Math.min(130,g.w/2);blocks.push({x:bx,y:g.y-96,w:36,h:36,kind:'bonus',used:false,broken:false,bump:0,reward:['grow','flower','star','coin'][j%4]});if(g.w>360){blocks.push({x:bx-36,y:g.y-96,w:36,h:36,kind:'brick',used:false,broken:false,bump:0});blocks.push({x:bx+36,y:g.y-96,w:36,h:36,kind:'brick',used:false,broken:false,bump:0})}}
 for(const [j,segment] of (plan.pipes||[]).entries()){const g=chunks[segment];pipes.push({x:g.x+g.w-100,y:g.y-56,w:64,h:56,bonus:j===0,used:false})}
 for(const [j,segment] of (plan.enemies||[]).entries()){const g=chunks[segment],ex=g.x+g.w*.6;const flying=plan.swim||(['sky','forest'].includes(plan.scene)&&j%2===0);enemies.push({x:ex,y:g.y,home:ex,baseY:g.y-65,vx:-(28+Math.floor(n/4)*3),type:flying?'bird':j===2&&n>7?'spike':'beetle',t:0,dead:false,floor:g.y})}
 for(const g of ground){if(g.x>=arenaStart)continue;for(let cx=g.x+55;cx<g.x+g.w-30;cx+=48)coins.push({x:cx,y:g.y-38,used:false})}
 for(const segment of plan.lift||[]){const g=chunks[segment];platforms.push({x:g.x+g.w-140,y:g.y-60,w:96,h:14,baseX:g.x+g.w-140,baseY:g.y-60,range:55,axis:n%2?'x':'y',phase:0,dx:0,dy:0,oneway:true});for(let k=0;k<3;k++)coins.push({x:g.x+g.w-115+k*26,y:g.y-150,used:false})}
 for(const segment of plan.spring||[]){const g=chunks[segment];springs.push({x:g.x+g.w-70,y:g.y,w:30,h:12})}
 for(const [j,segment] of (plan.belt||[]).entries()){const g=chunks[segment];g.belt=j%2?-65:65}
 for(const [j,segment] of (plan.jets||[]).entries()){const g=chunks[segment];hazards.push({x:g.x+g.w*.72,y:g.y,w:24,phase:j*.9,active:false})}
 const eligible=ground.filter(g=>g.w>=220&&g.x>width*.35&&g.x<arenaStart-200),cp=eligible[0]||ground[0];const checkpointX=cp===ground[0]?80:cp.x+35;
 const boss=n%4===3?{x:width-240,y:450,vy:0,hp:6,max:6,t:0,cool:2,inv:0,shield:false}:null;
 return {ground,blocks,pipes,enemies,coins,items,platforms,springs,hazards,width,boss,goal:width-110,bonus:false,checkpointX,plan,swim:!!plan.swim,ice:!!plan.ice,wind:plan.wind||0,current:plan.current||0,scene:plan.scene,arenaStart};
}
function updateMechanisms(dt){
 for(const p of level.platforms||[]){const oldX=p.x,oldY=p.y;p.phase+=dt;p.x=p.baseX+(p.axis==='x'?Math.sin(p.phase*1.3)*p.range:0);p.y=p.baseY+(p.axis==='y'?Math.sin(p.phase*1.2)*p.range:0);p.dx=p.x-oldX;p.dy=p.y-oldY;if(player.ground&&Math.abs(player.y-oldY)<3&&player.x+9>oldX&&player.x-9<oldX+p.w){player.x+=p.dx;player.y+=p.dy}}
 for(const h of level.hazards||[]){h.active=(clock+h.phase)%3.8>2.6;if(h.active&&overlap(body(),{x:h.x-12,y:h.y-57,w:24,h:57}))hurt()}
 for(const s of level.springs||[])if(player.ground&&Math.abs(player.y-s.y)<3&&Math.abs(player.x-s.x)<23){player.vy=-770;player.ground=false;player.coyote=0;sfx('jump')}
 if(player.ground){const g=level.ground.find(g=>Math.abs(player.y-g.y)<2&&player.x>g.x&&player.x<g.x+g.w);if(g?.belt)player.x+=g.belt*dt}
 if(!player.ground)player.x+=(level.wind||0)*dt;
 if(level.swim){player.x+=level.current*dt;player.swimClock=(player.swimClock||0)-dt;if(keys.jump&&player.swimClock<=0){player.jumpBuffer=.12;player.swimClock=.28}if(player.y-player.height<115){player.y=115+player.height;player.vy=Math.max(0,player.vy)}}
}
function drawMechanisms(){
 const t=theme();for(const p of level.platforms||[]){line([[p.baseX+p.w/2,p.baseY-p.range-35],[p.x+p.w/2,p.y]],t.accent+'aa',2);rect(p.x,p.y,p.w,p.h,'#427d79');rect(p.x,p.y,p.w,4,t.accent);for(let x=p.x+8;x<p.x+p.w;x+=18)rect(x,p.y+6,8,4,'#b3d8ba')}
 for(const s of level.springs||[]){line([[s.x-13,s.y-2],[s.x+10,s.y-5],[s.x-10,s.y-9],[s.x+10,s.y-13]],'#e6b67f',3);rect(s.x-17,s.y-16,34,5,'#d98569')}
 for(const h of level.hazards||[]){rect(h.x-15,h.y-5,30,5,'#515662');if(h.active){poly([[h.x-12,h.y],[h.x-9,h.y-27],[h.x-3,h.y-49],[h.x+2,h.y-60],[h.x+7,h.y-28],[h.x+12,h.y]],'#ec936e');poly([[h.x-6,h.y],[h.x,h.y-40],[h.x+6,h.y]],'#ffe2a0')}else circle(h.x,h.y-8,3+Math.sin(clock*8)*1.5,'#f8b579')}
 for(const g of level.ground)if(g.belt){rect(g.x,g.y,g.w,8,'#526d70');for(let x=g.x+((clock*g.belt)%24+24)%24;x<g.x+g.w-12;x+=24)label(g.belt>0?'›':'‹',x,g.y+8,'#f7db9e',14)}
}

function solids(){return [...level.ground,...level.blocks.filter(b=>!b.broken),...level.pipes,...(level.platforms||[])]}
function burst(x,y,color,count=12){for(let i=0;i<count;i++)particles.push({x,y,vx:(Math.random()-.5)*180,vy:-50-Math.random()*150,life:.3+Math.random()*.5,color,size:2+Math.random()*3})}
function notify(t,d=2){$('notice').textContent=t;noticeTimer=d}
function readProgress(){unlocked=clamp(parseInt(storage.get(profile('unlocked'),'0'),10)||0,0,31);selectedWorld=Math.floor(unlocked/4);selectedLevel=unlocked%4}
function renderMap(){const t=themes[selectedWorld];$('world-title').textContent=(selectedWorld+1)+'. '+t.name;$('world-description').textContent=stagePlans[selectedWorld*4+selectedLevel].name+' · '+({meadow:'Praderas y desniveles',cave:'Pasadizos subterráneos',forest:'Ramas y puentes',fortress:'Trampas y guardián',water:'Exploración bajo el agua',sky:'Islas y corrientes de viento',ice:'Suelo deslizante',desert:'Ruinas y dunas',night:'Azoteas y mecanismos',volcano:'Rocas y géiseres'})[stagePlans[selectedWorld*4+selectedLevel].scene];$('progress-label').textContent=(unlocked+1)+' / 32';$('worlds').innerHTML='';themes.forEach((w,i)=>{const b=document.createElement('button');b.textContent=w.icon;b.title=w.name;b.disabled=i*4>unlocked;b.setAttribute('aria-label','Mundo '+(i+1)+': '+w.name);b.setAttribute('aria-pressed',String(i===selectedWorld));b.onclick=()=>{selectedWorld=i;selectedLevel=Math.min(3,unlocked-i*4);index=selectedWorld*4+selectedLevel;level=createLevel(index);renderMap();if(!muted)startMusic(selectedWorld)};$('worlds').appendChild(b)});$('levels').innerHTML='';for(let i=0;i<4;i++){const b=document.createElement('button');b.textContent=(selectedWorld+1)+'–'+(i+1)+(i===3?' ✦':'');b.disabled=selectedWorld*4+i>unlocked;b.setAttribute('aria-pressed',String(i===selectedLevel));b.title=stagePlans[selectedWorld*4+i].name;b.onclick=()=>{selectedLevel=i;index=selectedWorld*4+i;level=createLevel(index);renderMap()};$('levels').appendChild(b)}$('record').textContent='Récord: '+storage.get(profile('best'),'0')+' · '+(storage.get(profile('complete'))==='1'?'¡Las ocho luces están a salvo!':'5 vidas al empezar · Avance guardado')}
function menu(){state='menu';keys={};bonusReturn=null;stopMusic();$('home').hidden=false;$('modal').hidden=true;$('manual').hidden=true;for(const id of ['hud','power','pause','keybar','touch','bossbar'])$(id).hidden=true;$('notice').textContent='';$('logout').hidden=!alias;$('login-panel').hidden=!!alias;$('ready-panel').hidden=!alias;$('user-name').textContent=alias.toUpperCase();document.body.classList.remove('playing');readProgress();index=selectedWorld*4+selectedLevel;level=createLevel(index);checkpoint=80;player=makePlayer();player.x=610;player.y=450;camera=200;particles=[];renderMap()}
function startLevel(n,fresh=false){index=clamp(n,0,31);level=createLevel(index);checkpoint=80;player=makePlayer();camera=0;bonusReturn=null;particles=[];sparks=[];hostile=[];bossActive=false;keys={};timeLeft=260;state='play';if(fresh){lives=5;coins=0;score=0}for(const id of ['home','modal','manual','bossbar'])$(id).hidden=true;for(const id of ['hud','power','pause','keybar','touch'])$(id).hidden=false;$('logout').hidden=true;document.body.classList.add('playing');$('hud-alias').textContent=alias.toUpperCase();$('track').textContent=stagePlans[index].name.toUpperCase()+(level.swim?' · MANTÉN SALTO PARA NADAR':level.wind?' · VIENTO':level.ice?' · HIELO':'');notify('MUNDO '+(Math.floor(index/4)+1)+'–'+(index%4+1)+' / '+stagePlans[index].name.toUpperCase(),2.5);startMusic(Math.floor(index/4));sfx('start');updateHUD()}
$('login').onsubmit=e=>{e.preventDefault();const v=$('alias').value.trim();if(v.length<2){$('alias').setCustomValidity('Escribe al menos dos caracteres.');$('alias').reportValidity();return}alias=v;storage.set('nimbo.alias',v);menu()};$('alias').oninput=()=> $('alias').setCustomValidity('');$('logout').onclick=()=>{alias='';storage.set('nimbo.alias','');menu()};$('start').onclick=()=>startLevel(selectedWorld*4+selectedLevel,true);$('menu').onclick=menu;
function dialog(label,title,copy,button){$('modal').hidden=false;$('result-label').textContent=label;$('result-title').textContent=title;$('result-copy').textContent=copy;$('continue').textContent=button}
function pause(){if(state==='paused'){state=previousState;$('modal').hidden=true;startMusic(Math.floor(index/4));return}if(!['play','dying'].includes(state))return;previousState=state;state='paused';keys={};stopMusic();dialog('UN PEQUEÑO DESCANSO','Las nubes pueden esperar.','Tu aventura continuará desde este mismo lugar.','CONTINUAR →')}
$('pause').onclick=pause;$('continue').onclick=()=>{if(state==='paused')pause();else if(state==='clear')startLevel(index+1);else if(state==='over')startLevel(index,true);else menu()};$('help').onclick=()=>{$('manual').hidden=false};$('close-help').onclick=()=>{$('manual').hidden=true};$('full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('full').title='Usa F11 para pantalla completa'}};
function press(k){keys[k]=true;if(k==='pause'){pause();return}if(state!=='play')return;if(k==='jump')player.jumpBuffer=.14;if(k==='down')enterPipe()}
window.addEventListener('keydown',e=>{if(e.target.matches('input'))return;const k=mapping[e.key.toLowerCase()];if(k){e.preventDefault();if(!e.repeat)press(k)}});window.addEventListener('keyup',e=>{const k=mapping[e.key.toLowerCase()];if(k){keys[k]=false;if(k==='jump'&&state==='play'&&player.vy<-210)player.vy=-210}});
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press(b.dataset.key)};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>{const k=b.dataset.key;keys[k]=false;if(k==='jump'&&state==='play'&&player.vy<-210)player.vy=-210}}
window.addEventListener('blur',()=>{keys={};if(['play','dying'].includes(state))pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopMusic();keys={};if(['play','dying'].includes(state))pause()}});
// Eight original melodies. No borrowed game music or audio samples.
let audio=null,muted=true,musicBus=null,musicTimer=null,musicNext=0,musicStep=0;
function tone(freq,t,dur,type='triangle',volume=.07,bus=null,end=null){if(!audio||muted)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(end)o.frequency.exponentialRampToValueAtTime(end,t+dur);g.gain.setValueAtTime(.001,t);g.gain.linearRampToValueAtTime(volume,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+dur);o.connect(g);g.connect(bus||audio.destination);o.start(t);o.stop(t+dur+.02);o.onended=()=>{o.disconnect();g.disconnect()}}
function sfx(kind){if(!audio||muted)return;const t=audio.currentTime;const sequence=(notes,delay=.07,dur=.13)=>notes.forEach((f,i)=>tone(f,t+i*delay,dur,'triangle',.09));switch(kind){case'jump':tone(220,t,.17,'square',.035,null,510);break;case'coin':sequence([990,1320],.065,.12);break;case'bump':tone(170,t,.08,'square',.055,null,80);break;case'break':sequence([160,100,65],.035,.07);break;case'power':sequence([330,440,550,660]);break;case'stomp':tone(180,t,.12,'triangle',.12,null,55);break;case'hurt':sequence([240,170,110],.06,.1);break;case'death':sequence([440,520,390,260,170],.12,.19);break;case'pipe':sequence([390,290,210,140],.08,.13);break;case'clear':sequence([392,494,587,740,784],.12,.3);break;case'life':sequence([520,780,1040,1300],.08,.22);break;case'fire':tone(700,t,.12,'sine',.06,null,180);break;case'checkpoint':sequence([440,550,880],.08,.17);break;case'start':sequence([330,440,660],.09,.18);break}}
function stopMusic(){if(musicTimer)clearInterval(musicTimer);musicTimer=null;if(musicBus){const old=musicBus;old.gain.setTargetAtTime(0,audio.currentTime,.03);setTimeout(()=>old.disconnect(),200);musicBus=null}}
function startMusic(world){stopMusic();if(muted||!audio||document.hidden||state==='paused')return;const d=themes[world];musicBus=audio.createGain();musicBus.gain.value=.32;musicBus.connect(audio.destination);musicStep=0;musicNext=audio.currentTime+.03;const schedule=()=>{const beat=60/d.bpm/2,hz=n=>440*2**((n-69)/12);if(musicNext<audio.currentTime-.2)musicNext=audio.currentTime+.01;while(musicNext<audio.currentTime+.13){const n=musicStep%16;tone(hz(d.root+d.notes[n]),musicNext,beat*.7,n%4?'triangle':'square',n%4?.13:.045,musicBus);if(n%2===0)tone(hz(d.root-24+(n>=8?5:0)),musicNext,beat*1.5,'triangle',.18,musicBus);if(n%4===0)tone(110,musicNext,.09,'sine',.20,musicBus,40);if(n%2)tone(3100,musicNext,.022,'square',.012,musicBus);if(n%8===0)for(const note of [0,4,7])tone(hz(d.root-12+note),musicNext,beat*3,'sine',.035,musicBus);musicStep++;musicNext+=beat}};schedule();musicTimer=setInterval(schedule,45)}
$('sound').onclick=async()=>{if(muted){try{audio??=new(window.AudioContext||window.webkitAudioContext)();await audio.resume();muted=false;startMusic(state==='menu'?selectedWorld:Math.floor(index/4))}catch{$('sound').textContent='AUDIO NO DISPONIBLE';return}}else{muted=true;stopMusic()}$('sound').textContent=muted?'♫ SONIDO OFF':'♫ SONIDO ON'};
function addCoin(count=1){coins+=count;score+=count*50;sfx('coin');while(coins>=50){coins-=50;lives=Math.min(99,lives+1);sfx('life');notify('¡UNA VIDA MÁS!',1.4)}}
function bump(block){block.bump=.18;if(block.kind==='bonus'&&!block.used){block.used=true;sfx('bump');if(block.reward==='coin'){addCoin(5);burst(block.x+18,block.y-10,'#ffe299')}else level.items.push({x:block.x+18,y:block.y-17,vx:35,vy:-90,type:block.reward,used:false});}else if(block.kind==='brick'){if(player.power>0){block.broken=true;score+=20;burst(block.x+18,block.y+15,theme().earth,18);sfx('break')}else sfx('bump')}}
function hurt(){if(state!=='play'||player.inv>0||player.star>0)return;if(player.power>0){player.power=0;player.height=30;player.inv=2;sfx('hurt');burst(player.x,player.y-20,'#fff0b2')}else die()}
function die(){if(state!=='play')return;state='dying';keys={};lives--;deathTimer=1.1;player.vy=-300;sfx('death');if(lives<=0)stopMusic()}
function respawn(){if(lives<=0){state='over';saveBest();dialog('TODAVÍA QUEDA AVENTURA','¡Otra oportunidad!','Puedes repetir este nivel con cinco vidas. Los niveles que desbloqueaste siguen disponibles.','VOLVER A INTENTAR →');return}if(bonusReturn){level=bonusReturn.level;checkpoint=bonusReturn.checkpoint;bonusReturn=null}player=makePlayer();camera=clamp(checkpoint-220,0,level.width-960);hostile=[];sparks=[];timeLeft=Math.max(timeLeft,90);if(bossActive&&level.boss){level.boss.hp=6;level.boss.cool=2;level.boss.inv=0;player.x=level.width-750}level.enemies.forEach(e=>{if(Math.abs(e.x-player.x)<170)e.dead=true});state='play';notify('¡TÚ PUEDES! / '+lives+' VIDAS',1.4)}
function saveBest(){if(score>(Number(storage.get(profile('best'),'0'))||0))storage.set(profile('best'),score)}
function finish(){if(state!=='play')return;if(level.bonus){leaveBonus();return}if(level.boss&&level.boss.hp>0)return;score+=500+Math.ceil(timeLeft)*5;saveBest();unlocked=Math.max(unlocked,Math.min(31,index+1));storage.set(profile('unlocked'),unlocked);keys={};stopMusic();sfx('clear');$('bossbar').hidden=true;if(index===31){state='victory';storage.set(profile('complete'),1);dialog('LAS OCHO LUCES HAN VUELTO','¡El cielo vuelve a brillar!','Nilo devuelve las luces a sus faros. Las islas se reúnen y los guardianes recuperan la calma. Gracias, '+alias+', por compartir esta aventura. Puntos: '+score+'.','VOLVER AL MAPA →')}else{state='clear';if(index%4===3)lives=Math.min(99,lives+1);dialog(index%4===3?'MUNDO COMPLETADO / LUZ RECUPERADA':'NIVEL COMPLETADO','¡Un salto más cerca!',index%4===3?'El guardián recupera su luz y abre el camino a otra isla. Has ganado una vida.':'El faro se ha encendido. Tu siguiente aventura ya está lista.','SIGUIENTE NIVEL →')}}
function enterPipe(){if(player.pipeLock>0)return;const pipe=level.pipes.find(p=>p.bonus&&!p.used&&Math.abs(player.x-(p.x+p.w/2))<19&&Math.abs(player.y-p.y)<3);if(!pipe)return;if(level.bonus){leaveBonus();return}pipe.used=true;bonusReturn={level,x:pipe.x+pipe.w+25,y:450,camera,checkpoint};bonusReturn.y=level.ground.find(g=>bonusReturn.x>g.x&&bonusReturn.x<g.x+g.w)?.y||450;level={ground:[{x:0,y:450,w:1120,h:120}],blocks:[],pipes:[{x:960,y:386,w:64,h:64,bonus:true}],enemies:[],coins:[],items:[],width:1120,boss:null,goal:1080,bonus:true};for(let i=0;i<22;i++)level.coins.push({x:150+i*34,y:390-Math.sin(i/21*Math.PI)*65,used:false});player.x=70;player.y=440;player.vx=0;player.vy=0;player.pipeLock=1;camera=0;keys={};hostile=[];sparks=[];sfx('pipe');notify('JARDÍN SECRETO / ¡RECOGE LAS MONEDAS!',2)}
function leaveBonus(){if(!bonusReturn)return;const back=bonusReturn;level=back.level;player.x=back.x;player.y=back.y;player.vy=0;player.pipeLock=1;camera=back.camera;checkpoint=back.checkpoint;bonusReturn=null;keys={};sfx('pipe');notify('¡DE VUELTA A LA AVENTURA!',1.4)}
function shoot(){if(player.power<2||player.cool>0)return;sparks.push({x:player.x+player.face*18,y:player.y-22,vx:player.face*380,vy:-90,life:2.2});player.cool=.28;sfx('fire')}
function enemyBox(e){return{x:e.x-14,y:e.y-(e.type==='bird'?14:24),w:28,h:e.type==='bird'?28:24}}
function defeat(e){if(e.dead)return;e.dead=true;score+=100;burst(e.x,e.y-12,'#f3d490');sfx('stomp')}
function hitBoss(){const b=level.boss;if(!b||b.hp<=0||b.inv>0||b.shield)return;b.hp--;b.inv=.8;score+=150;burst(b.x,b.y-40,theme().accent,20);sfx('stomp');if(b.hp===0){hostile=[];notify('¡GUARDIÁN LIBERADO! / ALCANZA EL FARO',2);$('bossbar').hidden=true}}
function updateBoss(dt){const b=level.boss;if(!b||!bossActive||b.hp<=0)return;b.t+=dt;b.cool-=dt;b.inv=Math.max(0,b.inv-dt);b.shield=b.t%4>2.6;b.vy+=1550*dt;b.y=Math.min(450,b.y+b.vy*dt);if(b.y===450)b.vy=0;if(b.cool<=0){const w=Math.floor(index/4),count=1+Math.floor(w/3);for(let i=0;i<count;i++){const a=Math.atan2(player.y-20-(b.y-30),player.x-b.x)+(i-(count-1)/2)*.23;hostile.push({x:b.x-20,y:b.y-30,vx:Math.cos(a)*(115+w*8),vy:Math.sin(a)*(115+w*8),life:6})}if(w%2===1)b.vy=-250;b.cool=1.65;}}
function update(dt){clock+=dt;if(noticeTimer>0){noticeTimer-=dt;if(noticeTimer<=0)$('notice').textContent=''}for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=380*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);if(state==='dying'){player.vy+=850*dt;player.y+=player.vy*dt;deathTimer-=dt;if(deathTimer<=0)respawn();return}if(state!=='play')return;timeLeft-=dt;if(timeLeft<=0){die();return}player.inv=Math.max(0,player.inv-dt);player.star=Math.max(0,player.star-dt);player.cool=Math.max(0,player.cool-dt);player.pipeLock=Math.max(0,player.pipeLock-dt);player.jumpBuffer=Math.max(0,player.jumpBuffer-dt);player.coyote=player.ground?.1:Math.max(0,player.coyote-dt);const dir=(keys.right?1:0)-(keys.left?1:0);if(dir)player.face=dir;const target=dir*(keys.run?315:205);player.vx+=(target-player.vx)*Math.min(1,dt*(level.ice?7:15));if(player.jumpBuffer>0&&(player.coyote>0||level.swim)){player.vy=level.swim?-230:-590;player.ground=false;player.coyote=0;player.jumpBuffer=0;sfx('jump')}updateMechanisms(dt);if(state!=='play')return;const list=solids();const oldX=player.x;player.x=clamp(player.x+player.vx*dt,bossActive&&!level.bonus?level.width-820:12,level.width-20);for(const s of list){if(s.oneway)continue;if(overlap(body(),s)){if(player.vx>0&&oldX+11<=s.x+1)player.x=s.x-11;else if(player.vx<0&&oldX-11>=s.x+s.w-1)player.x=s.x+s.w+11;player.vx=0}}
const oldY=player.y;player.vy+=(level.swim?360:1550)*dt;if(level.swim)player.vy=Math.min(player.vy,130);player.y+=player.vy*dt;player.ground=false;for(const s of list){if(player.x+10<=s.x||player.x-10>=s.x+s.w)continue;if(player.vy>=0&&oldY<=s.y+.6&&player.y>=s.y){player.y=s.y;player.vy=0;player.ground=true;break}else if(!s.oneway&&player.vy<0&&oldY-player.height>=s.y+s.h-.6&&player.y-player.height<=s.y+s.h){player.y=s.y+s.h+player.height;player.vy=60;if(s.kind)bump(s);break}}
if(player.y>600){die();return}if(dir&&player.ground)player.walk+=dt*Math.abs(player.vx)*.055;if(keys.fire)shoot();if(keys.down)enterPipe();
if(!level.bonus){const safe=level.checkpointX||80;if(player.x>safe&&checkpoint<safe){checkpoint=safe;notify('¡PUNTO DE CONTROL!',1.4);sfx('checkpoint')}if(level.boss&&!bossActive&&player.x>level.width-810){bossActive=true;checkpoint=level.width-750;$('bossbar').hidden=false;$('boss-name').textContent=theme().boss.toUpperCase();notify('GUARDIÁN / '+theme().boss.toUpperCase(),2)}}
camera=clamp(player.x-300,0,level.width-960);if(bossActive&&!level.bonus)camera=level.width-960;
for(const block of level.blocks)block.bump=Math.max(0,block.bump-dt);
for(const coin of level.coins)if(!coin.used&&overlap(body(),{x:coin.x-9,y:coin.y-12,w:18,h:24})){coin.used=true;addCoin();burst(coin.x,coin.y,'#f9d27c',5)}
for(const item of level.items){if(item.used)continue;const py=item.y;item.x+=item.vx*dt;item.vy+=700*dt;item.y+=item.vy*dt;for(const s of list)if(item.x>s.x-8&&item.x<s.x+s.w+8&&py+12<=s.y+1&&item.y+12>=s.y&&item.vy>=0){item.y=s.y-12;item.vy=0;break}if(overlap(body(),{x:item.x-12,y:item.y-12,w:24,h:24})){item.used=true;if(item.type==='star')player.star=8;else{player.power=Math.max(player.power,item.type==='flower'?2:1);const larger={x:player.x-11,y:player.y-42,w:22,h:42};player.height=list.some(s=>overlap(larger,s))?30:42}player.inv=Math.max(player.inv,.5);score+=200;burst(player.x,player.y-20,'#fff0b0',20);sfx('power');notify(item.type==='star'?'¡CRISTAL PROTECTOR!':item.type==='flower'?'¡FLOR DE CHISPAS! / PULSA J':'¡FRUTA DE ENERGÍA!',1.5)}}
if(player.power>0&&player.height===30&&!list.some(s=>overlap({x:player.x-11,y:player.y-42,w:22,h:42},s)))player.height=42;
for(const e of level.enemies){if(e.dead||e.x<camera-150||e.x>camera+1050)continue;e.t+=dt;if(e.type==='bird'){e.x=e.home+Math.sin(e.t)*65;e.y=e.baseY+Math.sin(e.t*2.4)*30}else{const next=e.x+e.vx*dt;const floor=level.ground.some(g=>next>g.x+16&&next<g.x+g.w-16&&Math.abs(g.y-e.floor)<2);const wall=level.pipes.some(p=>Math.abs(next-(p.x+p.w/2))<p.w/2+16);if(!floor||wall||Math.abs(next-e.home)>145)e.vx*=-1;else e.x=next}if(overlap(body(),enemyBox(e))){if(player.star>0)defeat(e);else if(player.vy>0&&oldY<=enemyBox(e).y+9&&e.type!=='spike'){defeat(e);player.vy=keys.jump?-400:-290}else hurt()}}
updateBoss(dt);if(level.boss&&bossActive&&level.boss.hp>0){const b=level.boss,bb={x:b.x-32,y:b.y-60,w:64,h:60};if(overlap(body(),bb)){if(!b.shield&&player.vy>0&&oldY<=bb.y+12){hitBoss();player.vy=-440}else if(player.star>0)hitBoss();else hurt()}}
for(const s of sparks){const prev=s.y;s.x+=s.vx*dt;s.vy+=650*dt;s.y+=s.vy*dt;s.life-=dt;for(const tile of list)if(s.x>tile.x&&s.x<tile.x+tile.w&&prev<=tile.y&&s.y>=tile.y&&s.vy>0){s.y=tile.y-3;s.vy=-210;break}for(const e of level.enemies)if(!e.dead&&overlap({x:s.x-5,y:s.y-5,w:10,h:10},enemyBox(e))){defeat(e);s.life=0;break}if(level.boss&&bossActive&&overlap({x:s.x-5,y:s.y-5,w:10,h:10},{x:level.boss.x-32,y:level.boss.y-60,w:64,h:60})){hitBoss();s.life=0}}sparks=sparks.filter(s=>s.life>0&&s.x>camera-50&&s.x<camera+1040&&s.y<600);
for(const b of hostile){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(overlap(body(),{x:b.x-6,y:b.y-6,w:12,h:12})){hurt();b.life=0}}hostile=hostile.filter(b=>b.life>0&&b.x>camera-100&&b.x<camera+1100&&b.y<600);
if(player.x>level.goal-18)finish();updateHUD()}
function updateHUD(){$('hud-level').textContent=(Math.floor(index/4)+1)+'–'+(index%4+1)+(level.bonus?' ✦':'');$('hud-coins').textContent='◆ '+String(coins).padStart(2,'0');$('hud-lives').textContent='♥ '+lives;$('hud-time').textContent=Math.max(0,Math.ceil(timeLeft));$('hud-score').textContent=String(score).padStart(6,'0');$('power').textContent=player.star>0?'✦ PROTECCIÓN / '+player.star.toFixed(1)+' s':player.power===2?'✿ FLOR DE CHISPAS / J PARA LANZAR':player.power===1?'✦ NILO / ENERGÍA EXTRA':'✦ NILO / EXPLORADOR';if(level.boss)$('boss-hp').style.width=(level.boss.hp/level.boss.max*100)+'%'}
let W=innerWidth,H=innerHeight,dpr=1,scale=1,ox=0,oy=0;
function resize(){W=innerWidth;H=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;scale=Math.min(W/960,H/540);ox=(W-960*scale)/2;oy=(H-540*scale)/2;c.imageSmoothingEnabled=false}window.addEventListener('resize',resize);resize();
function rect(x,y,w,h,color){c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),Math.ceil(w),Math.ceil(h))}
function poly(points,color){c.fillStyle=color;c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fill()}
function circle(x,y,r,color){c.fillStyle=color;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill()}
function line(points,color,width=2){c.strokeStyle=color;c.lineWidth=width;c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.stroke()}
function label(text,x,y,color,size=12){c.fillStyle=color;c.font='bold '+size+'px monospace';c.fillText(text,x,y)}
function cloud(x,y,s=1){c.save();c.translate(x,y);c.scale(s,s);circle(0,0,17,'#f6f7dc');circle(23,-10,24,'#f6f7dc');circle(49,0,18,'#f6f7dc');rect(-15,0,79,18,'#f6f7dc');rect(-4,17,56,3,'#e1ebd1');c.restore()}
function background(){const t=theme(),w=sceneTheme[level.scene]??Math.floor(index/4);rect(0,0,960,540,t.sky);if(w===1||level.bonus){for(let i=0;i<14;i++){const x=i*85-camera*.13%85;poly([[x,0],[x+27,95+(i%3)*20],[x+55,0]],t.far);poly([[x,460],[x+20,280+(i%4)*24],[x+50,460]],t.near)}for(let i=0;i<25;i++){const x=(i*139-camera*.1+9600)%960,y=70+(i*71)%290;poly([[x,y-5],[x+3,y],[x,y+5],[x-3,y]],t.accent+'70')}}else{circle(760-camera*.02,110,36,w>4?'#f0dcaf':'#fff2bf');circle(760-camera*.02,110,48,t.accent+'18');if(w>4)for(let i=0;i<36;i++)rect((i*139-camera*.05+9600)%960,45+(i*53)%230,2,2,'#fff1bf88');else for(let i=0;i<7;i++)cloud(i*190-(camera*.14%190)-30,95+(i%3)*35,.7+(i%2)*.25);for(let layer=0;layer<2;layer++)for(let i=-1;i<9;i++){const x=i*170-camera*(.16+layer*.15)%170,y=430+layer*15,h=75+((i+10)*37)%95,col=layer?t.near:t.far;if(w===2||w===4||w===7){poly([[x-80,y],[x+45,y-h],[x+175,y]],col);if(w===4)poly([[x+45,y-h],[x+12,y-h+37],[x+44,y-h+27],[x+78,y-h+40]],'#eff6df')}else if(w===6){rect(x,y-h,60,h,col);for(let j=0;j<4;j++)rect(x+j*18-4,y-h-12,12,15,col);rect(x+21,y-h+20,17,32,t.sky+'77')}else{circle(x+60,y,100+layer*20,col);circle(x+150,y+15,85,col)}}}
if(w===0||w===5)for(let i=-1;i<9;i++){const x=i*165-camera*.5%165;rect(x+20,310,12,140,w===0?'#82ad78':'#526b4e');circle(x+27,295,42,w===0?'#7cbb87':'#74975f');circle(x+1,317,29,w===0?'#87c293':'#7da262');circle(x+52,317,29,w===0?'#87c293':'#7da262');if(w===5)for(let j=0;j<3;j++)circle(x+Math.sin(clock+j)*25,260+j*40,2,'#f5ef93')}
if(w===3){for(let i=0;i<8;i++)cloud(i*150-camera*.4%150,390+(i%2)*25,1.4)}if(w===7){poly([[580,450],[730,180],[900,450]],'#955e6d');poly([[702,228],[730,180],[758,228],[730,217]],'#f8b87d');for(let i=0;i<12;i++)circle(730+Math.sin(clock+i)*22,180-(i*23+clock*18)%150,4,'#f4b98155')}
}
function sceneDetails(){
 if(level.scene==='fortress'){for(let i=-1;i<8;i++){const x=i*160-camera*.35%160;rect(x,70,34,380,'#34384955');rect(x-10,70,54,12,'#8d83a555');for(let y=100;y<430;y+=65)line([[x,y],[x+34,y]],'#c1b1b344',2)}rect(0,505,960,35,'#b4635c');for(let x=0;x<960;x+=27)rect(x,503+Math.sin(clock*3+x)*3,24,5,'#efb27b')}
 if(level.scene==='water'){rect(0,105,960,435,'#3a9cad60');for(let x=0;x<960;x+=24)line([[x,108+Math.sin(clock*2+x)*2],[x+22,108+Math.sin(clock*2+x+1)*2]],'#d4f0d5',2);for(let i=0;i<25;i++){const x=(i*139-camera*.2+9600)%960,y=120+(i*67-clock*25+10000)%360;c.strokeStyle='#d6f4df66';c.lineWidth=1;c.beginPath();c.arc(x,y,3+i%4,0,7);c.stroke()}for(let i=0;i<12;i++){const x=i*100-camera*.35%100;line([[x,480],[x+Math.sin(clock+i)*12,420],[x-7,385]],'#4a9684',6)}}
}
function drawWorld(){const t=theme(),w=sceneTheme[level.scene]??Math.floor(index/4);for(const g of level.ground){if(g.x>camera+990||g.x+g.w<camera-30)continue;rect(g.x,g.y,g.w,g.h,t.earth);rect(g.x,g.y,g.w,9,t.top);rect(g.x,g.y+9,g.w,5,'#ffffff20');for(let x=Math.max(g.x,Math.floor(camera/32)*32);x<Math.min(g.x+g.w,camera+990);x+=32){rect(x+3,g.y+24,12,6,'#ffffff18');rect(x+17,g.y+43,9,5,'#352e371c');rect(x+6,g.y+73,8,6,'#352e371c');if(w===0||w===5)poly([[x,g.y],[x+3,g.y-6],[x+7,g.y],[x+10,g.y-4],[x+13,g.y]],t.top)}}
for(const b of level.blocks){if(b.broken||b.x>camera+990||b.x+36<camera)continue;const y=b.y-Math.sin(b.bump/.18*Math.PI)*5;rect(b.x,y,36,36,'#684a42');rect(b.x+2,y+2,32,31,b.kind==='bonus'?(b.used?'#b09c80':'#f3bf67'):'#bf8b67');rect(b.x+3,y+3,29,3,'#ffe1a155');rect(b.x+3,y+31,29,3,'#77554755');if(b.kind==='bonus'){if(!b.used){label('✦',b.x+10,y+25,'#8a5837',22);rect(b.x+4,y+5,3,3,'#fff0bb');rect(b.x+28,y+26,3,3,'#9d693e')}}else{line([[b.x+2,y+17],[b.x+34,y+17]],'#855d4d',2);line([[b.x+18,y+2],[b.x+18,y+16]],'#855d4d',2);line([[b.x+9,y+18],[b.x+9,y+34]],'#855d4d',2)}}
for(const p of level.pipes){if(p.x>camera+990||p.x+p.w<camera)continue;rect(p.x+5,p.y+16,p.w-10,p.h-16,'#3f8e82');rect(p.x+9,p.y+16,9,p.h-16,'#8fc7a0');rect(p.x+p.w-16,p.y+16,8,p.h-16,'#26675f');rect(p.x,p.y,p.w,20,'#285f59');rect(p.x+3,p.y+3,p.w-6,13,'#5eaa90');rect(p.x+5,p.y+4,12,10,'#a1d3ac');if(p.bonus&&!p.used){circle(p.x+p.w/2,p.y-19,11,'#fff7dc');label('↓',p.x+p.w/2-5,p.y-14,'#2b7765',15)}}
if(!level.bonus){const x=level.checkpointX||80;const flagY=level.ground.find(g=>x>=g.x&&x<g.x+g.w)?.y||450;if(x>camera-30&&x<camera+990){rect(x,flagY-60,5,60,'#6c8772');poly([[x+5,flagY-60],[x+35,flagY-50],[x+5,flagY-37]],checkpoint>=x?'#f9d77f':'#91bca7');circle(x+2,flagY-62,4,'#fff0be')}}
const gx=level.goal;rect(gx-22,370,44,80,'#d6c1a0');rect(gx-27,367,54,10,'#679886');rect(gx-18,383,36,67,'#f4e9c8');poly([[gx-30,368],[gx,341],[gx+30,368]],'#4d8c79');circle(gx,354,10,'#f6d681');rect(gx-10,407,20,43,'#638b76');circle(gx,385,11,'#f4cb70');circle(gx,385,22,'#f4cb701a');}
function drawNilo(){if(player.inv>0&&Math.floor(clock*14)%2===0&&state!=='menu')return;c.save();c.translate(Math.round(player.x),Math.round(player.y));c.scale(player.face,player.height/30);const step=player.ground?Math.sin(player.walk)*3:2;if(player.star>0){circle(0,-16,23+Math.sin(clock*12)*3,'#fff0a445');for(let i=0;i<3;i++)circle(Math.cos(clock*6+i*2)*21,-16+Math.sin(clock*6+i*2)*21,2,'#fff4bb')}
rect(-7,-11,6,8,'#356d69');rect(1,-11,6,8,'#367d70');rect(-9-step,-4,10,4,'#6c5041');rect(1+step,-4,10,4,'#6c5041');rect(-8,-22,16,13,player.power===2?'#efad67':'#509e95');rect(-11,-20,5,11,'#ddaa7e');rect(7,-20,5,8,'#ddaa7e');rect(-9,-19,4,10,'#a47955');rect(-5,-31,15,12,'#f1c391');rect(-7,-32,18,6,'#e8be65');rect(-4,-35,14,5,'#f2d182');rect(9,-30,6,3,'#d89f4b');rect(3,-26,8,5,'#295e5c');rect(4,-26,3,2,'#d4e9d5');rect(-6,-21,17,3,'#e68a61');poly([[-6,-20],[-17,-15],[-11,-23]],'#dc7957');c.restore()}
function drawEnemy(e){if(e.dead||e.x<camera-50||e.x>camera+1010)return;const x=e.x,y=e.y;if(e.type==='bird'){poly([[x-13,y],[x-28,y-10+Math.sin(e.t*12)*8],[x-4,y-5],[x+15,y],[x+27,y+5],[x+12,y+8],[x-7,y+8]],'#c08096');rect(x+7,y-3,4,4,'#fff3cb');rect(x+10,y-2,2,2,'#36534c')}else{const step=Math.sin(e.t*9)*3;rect(x-15-step,y-4,11,4,'#4d5b4c');rect(x+5+step,y-4,11,4,'#4d5b4c');poly([[x-15,y-7],[x-14,y-18],[x-7,y-25],[x+7,y-25],[x+15,y-17],[x+16,y-7]],e.type==='spike'?'#8b7c9b':'#be8672');line([[x,y-24],[x,y-8]],'#785d67',2);rect(x-15,y-13,30,8,'#759583');rect(x-9,y-13,6,4,'#fff2cb');rect(x+4,y-13,6,4,'#fff2cb');rect(x-8,y-12,2,3,'#36594c');rect(x+7,y-12,2,3,'#36594c');if(e.type==='spike')for(let j=-1;j<=1;j++)poly([[x+j*10-4,y-21],[x+j*10,y-33],[x+j*10+5,y-21]],'#e2dfb9')}}
function drawBoss(){const b=level.boss;if(!b||!bossActive||b.hp<=0)return;c.save();c.translate(b.x,b.y);const t=theme(),w=Math.floor(index/4),col=b.inv>0?'#fff2c7':t.earth;rect(-30,-10,24,10,'#4c6261');rect(8,-10,24,10,'#4c6261');poly([[-29,-12],[-36,-48],[-22,-66],[20,-66],[36,-48],[28,-12]],col);rect(-24,-50,47,29,t.near);rect(-16,-44,11,8,'#fff2c7');rect(6,-44,11,8,'#fff2c7');rect(-12,-43,5,5,'#355b56');rect(7,-43,5,5,'#355b56');poly([[-5,-30],[0,-34],[6,-30],[0,-24]],t.accent);rect(-39,-44,10,25,col);rect(29,-44,10,25,col);if(w%3===0){poly([[-24,-61],[-26,-83],[-5,-66]],t.top);poly([[8,-66],[29,-82],[23,-59]],t.top)}else if(w%3===1){circle(-19,-64,12,t.accent);circle(20,-64,12,t.accent)}else{poly([[-21,-65],[-12,-88],[0,-73],[13,-88],[23,-65]],t.accent)}if(b.shield){c.strokeStyle=t.accent;c.lineWidth=4;c.beginPath();c.arc(0,-35,49,0,Math.PI*2);c.stroke()}else{circle(0,-76,6,t.accent);poly([[-4,-86],[0,-92],[4,-86]],'#fff4bf')}c.restore()}
function draw(){c.setTransform(dpr,0,0,dpr,0,0);rect(0,0,W,H,theme().sky);c.save();c.translate(ox,oy);c.scale(scale,scale);c.beginPath();c.rect(0,0,960,540);c.clip();background();sceneDetails();c.save();c.translate(-camera,0);drawWorld();drawMechanisms();
for(const coin of level.coins)if(!coin.used&&coin.x>camera-30&&coin.x<camera+990){const wid=4+Math.abs(Math.cos(clock*4+coin.x))*5;c.fillStyle='#e8ac4e';c.beginPath();c.ellipse(coin.x,coin.y,wid,11,0,0,Math.PI*2);c.fill();rect(coin.x-1,coin.y-7,2,14,'#fff1b4')}
for(const item of level.items)if(!item.used){const x=item.x,y=item.y;if(item.type==='grow'){circle(x-4,y,9,'#ed9e68');circle(x+4,y,9,'#efb16d');rect(x-1,y-12,3,6,'#7a7950');poly([[x,y-10],[x+10,y-15],[x+5,y-7]],'#77a46b')}else if(item.type==='flower'){for(let i=0;i<5;i++)circle(x+Math.cos(i*1.256)*7,y+Math.sin(i*1.256)*7,6,'#f4b475');circle(x,y,5,'#fff0b8')}else poly([[x,y-14],[x+10,y],[x,y+14],[x-10,y]],'#c8f0e1')}
for(const e of level.enemies)drawEnemy(e);drawBoss();drawNilo();for(const s of sparks){circle(s.x,s.y,6,'#f5b671');circle(s.x-1,s.y-1,3,'#fff1b3')}for(const b of hostile){circle(b.x,b.y,7,'#c48ca0');circle(b.x-2,b.y-2,3,'#f8ddc4')}for(const p of particles){c.globalAlpha=clamp(p.life*2,0,1);rect(p.x,p.y,p.size,p.size,p.color)}c.globalAlpha=1;c.restore();c.restore()}
function frame(now){const dt=Math.min((now-lastTime)/1000||0,.1);lastTime=now;if(state==='play'||state==='dying'){accumulator+=dt;while(accumulator>=1/120){update(1/120);accumulator-=1/120;if(!['play','dying'].includes(state)){accumulator=0;break}}}else{accumulator=0;if(state==='menu')clock+=dt}draw();requestAnimationFrame(frame)}
menu();requestAnimationFrame(frame);
